import React, { useState, useEffect, useRef } from "react";
import axios from "axios";
import { Client } from "@stomp/stompjs";
import SockJS from "sockjs-client";
import LudoBoard from "./LudoBoard";

export default function Match({ userEmail, onGameStart }) {
  const [entryFee, setEntryFee] = useState(13);
  const [status, setStatus] = useState("");
  const [game, setGame] = useState(null);
  const [playerId, setPlayerId] = useState(null);
  const [loading, setLoading] = useState(false);
  const [gameStarted, setGameStarted] = useState(false);

  // ✅ client রেফারেন্স রাখার জন্য useRef
  const stompClientRef = useRef(null);

  const ALLOWED_FEES = [13, 23, 50];

  // ✅ Match start হলে WebSocket connection তৈরি
  useEffect(() => {
    if (!game?.id || gameStarted) return;

    const token = localStorage.getItem("authToken");
    const socket = new SockJS(`http://localhost:8080/ludo-ws?token=${token}`);
    const client = new Client({
      webSocketFactory: () => socket,
      debug: (str) => console.log("🔧", str),
      onConnect: () => {
        console.log("🟢 WebSocket connected.");

        // ✅ ম্যাচের আপডেট সাবস্ক্রাইব করো
        client.subscribe(`/topic/match/${game.id}`, (message) => {
          const gameSession = JSON.parse(message.body);
          console.log("📩 ম্যাচ আপডেট:", gameSession);

          setGame(gameSession); // 🎯 আপডেট করো live game state

          const p1 = gameSession?.player1?.id;
          const p2 = gameSession?.player2?.id;

          console.log("👤 Player 1:", p1);
          console.log("👥 Player 2:", p2);

          if (p1 && p2 && !gameStarted) {
            console.log("✅ দুইজন প্লেয়ার ready, বোর্ডে রিডাইরেক্ট করছি...");
            setStatus("🎮 Game started! Redirecting...");
            setGameStarted(true);

            onGameStart({
              gameId: gameSession.id,
              playerId,
              entryFee,
            });
          } else {
            setStatus("🎉 Opponent পাওয়া গেছে, অপেক্ষা করছি...");
          }
        });
      },
      onStompError: (frame) => {
        console.error("❌ STOMP Error:", frame);
        setStatus("❌ WebSocket error হয়েছে!");
      },
    });

    client.activate();
    stompClientRef.current = client;

    return () => {
      if (stompClientRef.current) {
        stompClientRef.current.deactivate();
      }
    };
  }, [game?.id, gameStarted]);

  // ✅ ম্যাচ রিকোয়েস্ট পাঠানো
  const handleMatchRequest = async () => {
    if (!ALLOWED_FEES.includes(Number(entryFee))) {
      setStatus("❌ Invalid fee. 13, 23, 50 সিলেক্ট করো।");
      return;
    }

    setLoading(true);
    setStatus("🔍 Opponent খুঁজছি...");

    try {
      const token = localStorage.getItem("authToken");
      const response = await axios.post(
        "http://localhost:8080/api/match/start",
        { entryFee },
        {
          headers: {
            Authorization: `Bearer ${token}`,
            "Content-Type": "application/json",
          },
        }
      );

      const data = response.data;

      if (data.gameId) {
        setStatus("🎉 Match পাওয়া গেছে! অপেক্ষা করছি...");
        setGame({ id: data.gameId }); // শুধু ID সেট করি, পুরো অবজেক্ট WebSocket থেকে আসবে
        setPlayerId(data.playerId);
      } else {
        setStatus("⌛ অপেক্ষা করছি আরেকজন প্লেয়ারের জন্য...");
      }
    } catch (err) {
      console.error("❗ Server error:", err);
      setStatus("⚠️ " + (err.response?.data?.message || "Server error"));
    } finally {
      setLoading(false);
    }
  };

  // ✅ Debugging logs
  console.log("🎮 Game:", game);
  console.log("🚀 Game Started:", gameStarted);

  return (
    <div className="max-w-lg mx-auto mt-12 p-6 bg-white border rounded-xl shadow-lg">
      <h2 className="text-2xl font-bold text-center text-indigo-700 mb-6">
        🎲 Start a Ludo Match
      </h2>

      <div className="mb-5">
        <label className="block text-sm font-medium text-gray-700 mb-2">
          Select Entry Fee
        </label>
        <select
          value={entryFee}
          onChange={(e) => setEntryFee(Number(e.target.value))}
          className="w-full px-4 py-2 border rounded-md shadow-sm focus:outline-none focus:ring-indigo-500 focus:border-indigo-500"
        >
          {ALLOWED_FEES.map((fee) => (
            <option key={fee} value={fee}>
              ৳ {fee}
            </option>
          ))}
        </select>
      </div>

      <button
        onClick={handleMatchRequest}
        disabled={loading}
        className={`w-full py-2 px-4 text-white font-semibold rounded-md shadow-md transition ${
          loading
            ? "bg-gray-400 cursor-not-allowed"
            : "bg-indigo-600 hover:bg-indigo-700"
        }`}
      >
        {loading ? "⏳ Finding..." : "🔍 Find Opponent"}
      </button>

      {status && (
        <div className="mt-6 text-sm text-center text-gray-700">
          <strong>Status:</strong> {status}
        </div>
      )}

      {game?.id && (
        <div className="mt-6 p-4 text-center border border-green-400 bg-green-50 rounded-md">
          <p className="text-green-700 font-bold">✅ Game ID: {game.id}</p>
          <p className="text-green-600">👤 You are Player {playerId}</p>
        </div>
      )}

      {gameStarted && (
        <LudoBoard gameId={game.id} playerId={playerId} entryFee={entryFee} />
      )}
    </div>
  );
}
